#!/usr/bin/env node
/**
 * tred-quota-et-credits.mjs
 *
 * Les quatre pièces qui manquaient autour du quota :
 *
 *   1. Un bandeau au-dessus du champ de saisie — « il te reste 4 questions »,
 *      à partir d'un cinquième du forfait.
 *   2. Une alerte poussée le soir, à 90 %, une seule fois par mois, et
 *      seulement pour ceux qui n'ont aucun crédit en réserve.
 *   3. L'annonce AVANT la dépense quand le solde prend le relais du quota —
 *      jusqu'ici les crédits se débitaient sans un mot.
 *   4. Une page /credits sur le web : le mur mène à l'achat, plus à la page
 *      des tarifs. Le mobile l'avait déjà.
 *
 * Contient aussi tout ce qui n'est pas encore poussé : le guide de premier
 * lancement, les Fächer, la relance du soir, le garde-fou du tuteur, et le
 * correctif « le chat dit pourquoi il refuse ».
 *
 * Vérifié ici : tsc 0 (web + mobile), oxlint 0, bun test 126/126,
 * vite build, expo export.
 *
 *   node tred-quota-et-credits.mjs
 */
import { writeFileSync, mkdirSync, existsSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = resolve(depart);
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const parent = dirname(d);
      if (parent === d) break;
      d = parent;
    }
  }
  return null;
}

const R = racine();
if (!R) {
  console.error("Depot introuvable. Lance-le depuis C:\\dev\\tred-rdm\\aerostudy-ai.");
  process.exit(1);
}
console.log("Depot :", R, "\n");

const PAYLOAD = "";

const LOT = JSON.parse(inflateSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));

let n = 0;
for (const [chemin, b64] of Object.entries(LOT.ecrire)) {
  const cible = join(R, chemin);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  n++;
}
for (const chemin of LOT.supprimer) {
  const cible = join(R, chemin);
  if (existsSync(cible)) rmSync(cible);
}

console.log(`${n} fichiers poses.\n`);
console.log("Ensuite :");
console.log("  git add -A");
console.log("  git commit -m \"quota visible, credits annonces, page de recharge web\"");
console.log("  git push");
